## Option 2: BLoC-Based Integration

### Step 1: Add Event to Your DashboardBloc

```dart
// lib/features/dashboard/presentation/bloc/dashboard_event.dart

abstract class DashboardEvent extends Equatable {
  const DashboardEvent();
}

class InitializeDashboardEvent extends DashboardEvent {
  final String email;
  final String userId;
  final String token;

  const InitializeDashboardEvent({
    required this.email,
    required this.userId,
    required this.token,
  });

  @override
  List<Object> get props => [email, userId, token];
}
```

### Step 2: Add Handler to Your DashboardBloc

```dart
// lib/features/dashboard/presentation/bloc/dashboard_bloc.dart

class DashboardBloc extends Bloc<DashboardEvent, DashboardState> {
  DashboardBloc() : super(const DashboardState.initial()) {
    on<InitializeDashboardEvent>(_onInitializeDashboard);
  }

  Future<void> _onInitializeDashboard(
    InitializeDashboardEvent event,
    Emitter<DashboardState> emit,
  ) async {
    emit(const DashboardState.loading());
    try {
      // Store token if needed
      _storageService.saveToken(event.token);

      // Fetch dashboard data
      final dashboardData = await _dashboardRepository.fetchDashboard(
        userId: event.userId,
        token: event.token,
      );

      emit(DashboardState.loaded(
        dashboardData: dashboardData,
        userEmail: event.email,
        userId: event.userId,
      ));
    } catch (e) {
      emit(DashboardState.error(message: e.toString()));
    }
  }
}
```

### Step 3: Update dashboard_page.dart for BLoC

```dart
Future<void> _getUserSessionFromAndroid() async {
  try {
    final result = await platform.invokeMethod<Map>('getUserSession');

    if (result != null) {
      final email = result['email'] as String?;
      final userId = result['userId'] as String?;
      final token = result['token'] as String?;

      // Dispatch event to BLoC
      if (mounted && email != null && userId != null && token != null) {
        context.read<DashboardBloc>().add(
          InitializeDashboardEvent(
            email: email,
            userId: userId,
            token: token,
          ),
        );
      }
    }
  } on PlatformException catch (e) {
    // Error handling
  }
}
```

