## 2. FlutterDashboardActivity.kt - Complete File (NEW)

```kotlin
package com.example.androidapp.ui

import android.os.Bundle
import io.flutter.embedding.android.FlutterActivity
import com.example.androidapp.ChannelManager
import timber.log.Timber

class FlutterDashboardActivity : FlutterActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        // Extract authenticated user data from intent extras
        val email = intent.getStringExtra("email")
        val userId = intent.getStringExtra("userId")
        val token = intent.getStringExtra("token")

        // Store user session in ChannelManager for Flutter to access
        if (!email.isNullOrEmpty() && !userId.isNullOrEmpty() && !token.isNullOrEmpty()) {
            ChannelManager.setUserSession(email, userId, token)
            Timber.d("User session set for dashboard: $email")
        } else {
            Timber.w("Missing user data in FlutterDashboardActivity intent")
        }
    }

    override fun onDestroy() {
        super.onDestroy()
        // Clear session when activity is destroyed
        ChannelManager.clearUserSession()
    }
}
```

