package com.example.androidapp.services

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.media.RingtoneManager
import android.os.Build
import androidx.core.app.NotificationCompat
import com.example.androidapp.AuthApplication
import com.example.androidapp.R
import com.example.androidapp.ui.MainActivity
import com.example.androidapp.utils.FCMHelper
import com.google.firebase.messaging.FirebaseMessagingService
import com.google.firebase.messaging.RemoteMessage
import timber.log.Timber

class MyFirebaseMessagingService : FirebaseMessagingService() {

    override fun onMessageReceived(remoteMessage: RemoteMessage) {
        super.onMessageReceived(remoteMessage)

        Timber.d("FCM Message received from: ${remoteMessage.from}")

        val firebaseAnalytics = (application as AuthApplication).firebaseAnalytics

        // Check if message contains a notification payload
        remoteMessage.notification?.let {
            Timber.d("Message Notification Body: ${it.body}")

            // Log notification received to Analytics
            FCMHelper.logNotificationReceived(
                firebaseAnalytics,
                remoteMessage.data["type"] ?: FCMHelper.NotificationTypes.GENERAL,
                remoteMessage.messageId
            )

            sendNotification(it.title, it.body, remoteMessage.data["type"])
        }

        // Check if message contains a data payload
        if (remoteMessage.data.isNotEmpty()) {
            Timber.d("Message data payload: ${remoteMessage.data}")
            handleDataPayload(remoteMessage.data)
        }
    }

    override fun onNewToken(token: String) {
        super.onNewToken(token)
        Timber.d("Refreshed FCM token: $token")

        // If you want to send messages to this application instance or
        // manage this app's subscriptions on the server side, send the
        // FCM registration token to your app server.
        sendRegistrationToServer(token)
    }

    private fun handleDataPayload(data: Map<String, String>) {
        // Handle custom data payload here
        val title = data["title"]
        val body = data["body"]
        val type = data["type"]

        val firebaseAnalytics = (application as AuthApplication).firebaseAnalytics

        // Log notification received to Analytics
        FCMHelper.logNotificationReceived(
            firebaseAnalytics,
            type ?: FCMHelper.NotificationTypes.GENERAL
        )

        when (type) {
            "payment_status" -> {
                // Handle payment notification
                sendNotification(title, body, type)
            }
            "promotion" -> {
                // Handle promotion notification
                sendNotification(title, body, type)
            }
            else -> {
                sendNotification(title, body, type)
            }
        }
    }

    private fun sendNotification(title: String?, messageBody: String?, type: String? = null) {
        val intent = Intent(this, MainActivity::class.java).apply {
            addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)
            putExtra("notification_type", type)
        }

        val pendingIntent = PendingIntent.getActivity(
            this,
            0,
            intent,
            PendingIntent.FLAG_ONE_SHOT or PendingIntent.FLAG_IMMUTABLE
        )

        val channelId = getString(R.string.default_notification_channel_id)
        val defaultSoundUri = RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION)

        val notificationBuilder = NotificationCompat.Builder(this, channelId)
            .setSmallIcon(R.drawable.ic_notification_bell)
            .setContentTitle(title ?: "Notification")
            .setContentText(messageBody ?: "")
            .setAutoCancel(true)
            .setSound(defaultSoundUri)
            .setContentIntent(pendingIntent)
            .setPriority(NotificationCompat.PRIORITY_HIGH)

        val notificationManager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

        // Since Android Oreo notification channel is needed
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(
                channelId,
                "General Notifications",
                NotificationManager.IMPORTANCE_HIGH
            ).apply {
                description = "Channel for general app notifications"
            }
            notificationManager.createNotificationChannel(channel)
        }

        val notificationId = System.currentTimeMillis().toInt()
        notificationManager.notify(notificationId, notificationBuilder.build())
    }

    private fun sendRegistrationToServer(token: String) {
        // TODO: Implement this method to send token to your app server
        Timber.d("Sending token to server: $token")

        // Example: You might want to save this token to SharedPreferences
        // and send it to your backend API
        val sharedPreferences = getSharedPreferences("FCM_PREFS", Context.MODE_PRIVATE)
        sharedPreferences.edit().putString("FCM_TOKEN", token).apply()
    }

    companion object {
        private const val TAG = "FCMService"
    }
}

package com.example.androidapp.services

import android.Manifest
import android.app.ActivityManager
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.media.RingtoneManager
import android.os.Build
import android.os.Handler
import android.os.Looper
import android.widget.Toast
import androidx.core.app.ActivityCompat
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import com.example.androidapp.AuthApplication
import com.example.androidapp.R
import com.example.androidapp.ui.MainActivity
import com.example.androidapp.utils.FCMHelper
import com.google.firebase.messaging.FirebaseMessagingService
import com.google.firebase.messaging.RemoteMessage
import timber.log.Timber

class MyFirebaseMessagingService : FirebaseMessagingService() {

    override fun onMessageReceived(remoteMessage: RemoteMessage) {
        super.onMessageReceived(remoteMessage)

        Timber.d("FCM Message received from: ${remoteMessage.from}")

        val firebaseAnalytics = (application as AuthApplication).firebaseAnalytics

        // Check if message contains a notification payload
        remoteMessage.notification?.let {
            Timber.d("Message Notification Body: ${it.body}")

            // Log notification received to Analytics
            FCMHelper.logNotificationReceived(
                firebaseAnalytics,
                remoteMessage.data["type"] ?: FCMHelper.NotificationTypes.GENERAL,
                remoteMessage.messageId
            )

            sendNotification(it.title, it.body, remoteMessage.data["type"])
        }

        // Check if message contains a data payload
        if (remoteMessage.data.isNotEmpty()) {
            Timber.d("Message data payload: ${remoteMessage.data}")
            handleDataPayload(remoteMessage.data)
        }
    }

    override fun onNewToken(token: String) {
        super.onNewToken(token)
        Timber.d("Refreshed FCM token: $token")

        // If you want to send messages to this application instance or
        // manage this app's subscriptions on the server side, send the
        // FCM registration token to your app server.
        sendRegistrationToServer(token)
    }

    private fun handleDataPayload(data: Map<String, String>) {
        // Handle custom data payload here
        val title = data["title"]
        val body = data["body"]
        val type = data["type"]

        val firebaseAnalytics = (application as AuthApplication).firebaseAnalytics

        // Log notification received to Analytics
        FCMHelper.logNotificationReceived(
            firebaseAnalytics,
            type ?: FCMHelper.NotificationTypes.GENERAL
        )

        when (type) {
            "payment_status" -> {
                // Handle payment notification
                sendNotification(title, body, type)
            }
            "promotion" -> {
                // Handle promotion notification
                sendNotification(title, body, type)
            }
            else -> {
                sendNotification(title, body, type)
            }
        }
    }

    private fun sendNotification(title: String?, messageBody: String?, type: String? = null) {
        Timber.d("sendNotification called - Title: $title, Body: $messageBody, Type: $type")

        // Check if app is in foreground
        val isAppInForeground = isAppInForeground()
        Timber.d("Is app in foreground: $isAppInForeground")

        // If app is in foreground, show an in-app notification (Toast)
        if (isAppInForeground) {
            showInAppNotification(title, messageBody)
        }

        // Check notification permission for Android 13+
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (ActivityCompat.checkSelfPermission(
                    this,
                    Manifest.permission.POST_NOTIFICATIONS
                ) != PackageManager.PERMISSION_GRANTED
            ) {
                Timber.e("POST_NOTIFICATIONS permission not granted! Cannot show notification.")
                return
            } else {
                Timber.d("POST_NOTIFICATIONS permission is granted")
            }
        }

        val intent = Intent(this, MainActivity::class.java).apply {
            addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)
            putExtra("notification_type", type)
        }

        val pendingIntent = PendingIntent.getActivity(
            this,
            0,
            intent,
            PendingIntent.FLAG_ONE_SHOT or PendingIntent.FLAG_IMMUTABLE
        )

        val channelId = getString(R.string.default_notification_channel_id)
        Timber.d("Using channel ID: $channelId")

        val defaultSoundUri = RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION)

        val notificationBuilder = NotificationCompat.Builder(this, channelId)
            .setSmallIcon(R.drawable.ic_notification_bell)
            .setContentTitle(title ?: "Notification")
            .setContentText(messageBody ?: "")
            .setAutoCancel(true)
            .setSound(defaultSoundUri)
            .setContentIntent(pendingIntent)
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setDefaults(NotificationCompat.DEFAULT_ALL)
            .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)

        val notificationManager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

        // Create notification channel for Android Oreo and above
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val existingChannel = notificationManager.getNotificationChannel(channelId)
            if (existingChannel == null) {
                Timber.d("Creating notification channel: $channelId")
                val channel = NotificationChannel(
                    channelId,
                    "General Notifications",
                    NotificationManager.IMPORTANCE_HIGH
                ).apply {
                    description = "Channel for general app notifications"
                    enableLights(true)
                    enableVibration(true)
                }
                notificationManager.createNotificationChannel(channel)
                Timber.d("Notification channel created successfully")
            } else {
                Timber.d("Notification channel already exists")
            }
        }

        // Check if notifications are enabled
        if (!NotificationManagerCompat.from(this).areNotificationsEnabled()) {
            Timber.e("Notifications are disabled for this app!")
            return
        }

        val notificationId = System.currentTimeMillis().toInt()
        Timber.d("Posting notification with ID: $notificationId")

        try {
            notificationManager.notify(notificationId, notificationBuilder.build())
            Timber.d("✅ Notification posted successfully! Swipe down notification shade to see it.")
        } catch (e: Exception) {
            Timber.e(e, "❌ Failed to post notification")
        }
    }

    private fun isAppInForeground(): Boolean {
        val activityManager = getSystemService(Context.ACTIVITY_SERVICE) as ActivityManager
        val runningProcesses = activityManager.runningAppProcesses ?: return false

        for (processInfo in runningProcesses) {
            if (processInfo.importance == ActivityManager.RunningAppProcessInfo.IMPORTANCE_FOREGROUND) {
                if (processInfo.processName == packageName) {
                    return true
                }
            }
        }
        return false
    }

    private fun showInAppNotification(title: String?, message: String?) {
        Handler(Looper.getMainLooper()).post {
            Toast.makeText(
                this,
                " $title: $message",
                Toast.LENGTH_LONG
            ).show()
            Timber.d(" In-app notification shown: $title - $message")
        }
    }

    private fun sendRegistrationToServer(token: String) {
        // TODO: Implement this method to send token to your app server
        Timber.d("Sending token to server: $token")

        // Example: You might want to save this token to SharedPreferences
        // and send it to your backend API
        val sharedPreferences = getSharedPreferences("FCM_PREFS", Context.MODE_PRIVATE)
        sharedPreferences.edit().putString("FCM_TOKEN", token).apply()
    }

    companion object {
        private const val TAG = "FCMService"
    }
}

package com.example.androidapp.ui.debug

import android.content.ClipData
import android.content.ClipboardManager
import android.content.Context
import android.os.Bundle
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import com.example.androidapp.AuthApplication
import com.example.androidapp.databinding.ActivityDebugFcmBinding
import com.example.androidapp.utils.FCMHelper
import timber.log.Timber

/**
 * Debug Activity to view and copy FCM Token
 * Use this to get your FCM token for testing notifications
 */
class DebugFCMActivity : AppCompatActivity() {

    private lateinit var binding: ActivityDebugFcmBinding

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityDebugFcmBinding.inflate(layoutInflater)
        setContentView(binding.root)

        // Get saved token from SharedPreferences
        val savedToken = (application as AuthApplication).getFCMToken()

        if (savedToken != null) {
            displayToken(savedToken)
        } else {
            binding.tvToken.text = "Fetching token..."
            fetchFCMToken()
        }

        // Refresh button
        binding.btnRefreshToken.setOnClickListener {
            binding.tvToken.text = "Fetching token..."
            fetchFCMToken()
        }

        // Copy button
        binding.btnCopyToken.setOnClickListener {
            val token = binding.tvToken.text.toString()
            if (token.isNotEmpty() && token != "No token available" && token != "Fetching token...") {
                copyToClipboard(token)
                Toast.makeText(this, "Token copied to clipboard!", Toast.LENGTH_SHORT).show()
            } else {
                Toast.makeText(this, "No token to copy", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun fetchFCMToken() {
        FCMHelper.getToken { token ->
            runOnUiThread {
                if (token != null) {
                    displayToken(token)
                    Timber.d("FCM Token retrieved: $token")
                } else {
                    binding.tvToken.text = "No token available"
                    Toast.makeText(this, "Failed to get FCM token", Toast.LENGTH_SHORT).show()
                }
            }
        }
    }

    private fun displayToken(token: String) {
        binding.tvToken.text = token
        binding.tvTokenInfo.text = "Token length: ${token.length} characters\n\n" +
                "Use this token to send test notifications from:\n" +
                "• Firebase Console\n" +
                "• Your backend server\n" +
                "• cURL/Postman"
    }

    private fun copyToClipboard(text: String) {
        val clipboard = getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
        val clip = ClipData.newPlainText("FCM Token", text)
        clipboard.setPrimaryClip(clip)
    }
}

package com.example.androidapp.utils

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build
import androidx.core.app.NotificationCompat
import com.example.androidapp.R
import com.example.androidapp.ui.MainActivity

object NotificationHelper {

    const val CHANNEL_ID_GENERAL = "general_channel"
    const val CHANNEL_ID_PAYMENT = "payment_channel"
    const val CHANNEL_ID_PROMOTION = "promotion_channel"

    fun createNotificationChannels(context: Context) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

            // General channel
            val generalChannel = NotificationChannel(
                CHANNEL_ID_GENERAL,
                "General Notifications",
                NotificationManager.IMPORTANCE_DEFAULT
            ).apply {
                description = "General app notifications"
            }

            // Payment channel
            val paymentChannel = NotificationChannel(
                CHANNEL_ID_PAYMENT,
                "Payment Notifications",
                NotificationManager.IMPORTANCE_HIGH
            ).apply {
                description = "Payment related notifications"
            }

            // Promotion channel
            val promotionChannel = NotificationChannel(
                CHANNEL_ID_PROMOTION,
                "Promotion Notifications",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Promotional notifications"
            }

            notificationManager.createNotificationChannel(generalChannel)
            notificationManager.createNotificationChannel(paymentChannel)
            notificationManager.createNotificationChannel(promotionChannel)
        }
    }

    fun showNotification(
        context: Context,
        title: String,
        message: String,
        channelId: String = CHANNEL_ID_GENERAL
    ) {
        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

        val intent = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
        }

        val pendingIntent = PendingIntent.getActivity(
            context,
            0,
            intent,
            PendingIntent.FLAG_IMMUTABLE
        )

        val notification = NotificationCompat.Builder(context, channelId)
            .setSmallIcon(R.drawable.ic_notification_bell)
            .setContentTitle(title)
            .setContentText(message)
            .setStyle(NotificationCompat.BigTextStyle().bigText(message))
            .setPriority(NotificationCompat.PRIORITY_DEFAULT)
            .setContentIntent(pendingIntent)
            .setAutoCancel(true)
            .build()

        val notificationId = System.currentTimeMillis().toInt()
        notificationManager.notify(notificationId, notification)
    }
}
